/**
 * Legacy SVG→PNG generator for text OG cards and diagrams.
 * Do not run this: it overwrites photographic covers with HTML-style text cards.
 * Covers live in public/images/*.jpg. SERP, maps, and icons stay HTML/SVG.
 */

import { mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { gunzipSync } from 'node:zlib';
import sharp from 'sharp';

