const INK = '#17140f';
const MUTED = '#4b453b';
const PAPER = '#f2ede3';
const PAPER2 = '#e9e2d4';
const RULE = '#cbc1ae';
const SIGNAL = '#ff4d1a';

/** Advance widths at 1000 UPM, Bricolage Grotesque wght 800. */
const DISPLAY = {"0":670,"1":360,"2":613,"3":611,"4":638,"5":615,"6":662,"7":517,"8":661,"9":658,"A":712,"B":692,"C":685,"D":705,"E":632,"F":601,"G":729,"H":730,"I":303,"J":382,"K":697,"L":509,"M":955,"N":790,"O":725,"P":654,"Q":726,"R":688,"S":658,"T":579,"U":733,"V":682,"W":1001,"X":719,"Y":662,"Z":576,"a":595,"b":648,"c":571,"d":649,"e":587,"f":408,"g":607,"h":643,"i":286,"j":288,"k":605,"l":283,"m":963,"n":643,"o":612,"p":648,"q":649,"r":446,"s":549,"t":406,"u":634,"v":585,"w":881,"x":587,"y":608,"z":537," ":223,".":252,",":212,"·":252,"&":754,"–":545,"—":821,"'":187,"’":219,":":262,"/":365,"-":359,"(":329,")":329,"+":534,"?":425,"!":303};

/** Advance widths at 1000 UPM, Instrument Sans wght 600 (labels). */
const SANS = {"0":677,"1":387,"2":557,"3":579,"4":615,"5":581,"6":615,"7":561,"8":598,"9":619,"A":733,"B":645,"C":747,"D":755,"E":630,"F":594,"G":764,"H":725,"I":254,"J":427,"K":712,"L":589,"M":898,"N":725,"O":794,"P":667,"Q":806,"R":664,"S":637,"T":664,"U":704,"V":733,"W":1087,"X":707,"Y":700,"Z":631,"a":558,"b":621,"c":552,"d":621,"e":571,"f":370,"g":621,"h":612,"i":260,"j":260,"k":558,"l":260,"m":941,"n":612,"o":597,"p":621,"q":621,"r":390,"s":494,"t":406,"u":604,"v":536,"w":800,"x":587,"y":536,"z":513," ":193,".":275,",":275,"·":144,"&":768,"–":599,"—":899,"'":256,"’":275,":":275,"/":444,"-":493,"(":439,")":439,"+":544,"?":580,"!":295};

const BRICOLAGE_GZ = '';
const INSTRUMENT_GZ = '';

let fontFaces = '';

function initFonts() {
  const bricolage = gunzipSync(Buffer.from(BRICOLAGE_GZ, 'base64'));
  const instrument = gunzipSync(Buffer.from(INSTRUMENT_GZ, 'base64'));
  if (bricolage.readUInt32BE(0) !== 0x00010000 || instrument.readUInt32BE(0) !== 0x00010000) {
    throw new Error('Embedded fonts did not decode to TrueType');
  }
  const face = (family, buf) => `@font-face { font-family: '${family}'; src: url('data:font/ttf;base64,${buf.toString('base64')}') format('truetype'); font-weight: 100 900; font-style: normal; }`;
  fontFaces = `${face('Bricolage Grotesque', bricolage)}\n${face('Instrument Sans', instrument)}`;
}

function esc(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function measure(text, size, table, tracking) {
  let width = 0;
  for (const ch of text) {
    const adv = table[ch];
    if (adv == null) {
      width += (table.n || 600) * size / 1000;
    } else {
      width += adv * size / 1000;
    }
  }
  if (text.length > 1) width += (text.length - 1) * tracking;
  return width;
}

function linePenalty(line) {
  const words = line.split(' ');
  const last = words[words.length - 1] || '';
  let penalty = 0;
  if (/[&:,]$/.test(line)) penalty += 800;
  if (/^(a|an|the|of|in|on|for|and|to|or|&)$/i.test(last)) penalty += 500;
  if (last.length > 0 && last.length <= 2) penalty += 200;
  if (words.length === 1 && words[0].length < 4) penalty += 300;
  return penalty;
}

/**
 * Largest size whose balanced wrap fits in maxLines.
 * Widths include a small kerning safety margin via maxWidth.
 */
function fitTitle(text, maxWidth, { maxSize = 92, minSize = 46, maxLines = 3 } = {}) {
  const words = text.split(/\s+/).filter(Boolean);
  for (let size = maxSize; size >= minSize; size -= 2) {
    const tracking = -0.032 * size;
    const widthOf = (slice) => measure(slice.join(' '), size, DISPLAY, tracking);
    if (words.length === 1 || widthOf(words) <= maxWidth) {
      if (widthOf(words) <= maxWidth) return { size, tracking, lines: [words.join(' ')] };
    }
    let best = null;
    const consider = (lines) => {
      if (lines.some((line) => line.length === 0)) return;
      const slices = lines.map((line) => line.split(' '));
      if (slices.some((slice) => widthOf(slice) > maxWidth)) return;
      const widths = slices.map(widthOf);
      const score = (Math.max(...widths) - Math.min(...widths)) + lines.reduce((sum, line) => sum + linePenalty(line), 0);
      if (!best || score < best.score) best = { score, lines };
    };
    if (maxLines >= 2) {
      for (let i = 1; i < words.length; i += 1) {
        consider([words.slice(0, i).join(' '), words.slice(i).join(' ')]);
      }
    }
    if (maxLines >= 3) {
      for (let i = 1; i < words.length - 1; i += 1) {
        for (let j = i + 1; j < words.length; j += 1) {
          consider([
            words.slice(0, i).join(' '),
            words.slice(i, j).join(' '),
            words.slice(j).join(' '),
          ]);
        }
      }
    }
    if (best) return { size, tracking, lines: best.lines };
  }
  const size = minSize;
  const tracking = -0.032 * size;
  const lines = [];
  let current = '';
  for (const word of words) {
    const trial = current ? `${current} ${word}` : word;
    if (measure(trial, size, DISPLAY, tracking) <= maxWidth) current = trial;
    else {
      if (current) lines.push(current);
      current = word;
    }
  }
  if (current) lines.push(current);
  return { size, tracking, lines: lines.slice(0, maxLines) };
}

function svgDoc(width, height, body, viewW = width, viewH = height) {
  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${viewW} ${viewH}">
<style><![CDATA[
${fontFaces}
.d { font-family: 'Bricolage Grotesque', Georgia, serif; font-weight: 800; fill: ${INK}; }
.s { font-family: 'Instrument Sans', 'Helvetica Neue', Arial, sans-serif; font-weight: 600; fill: ${MUTED}; }
.p { font-family: 'Instrument Sans', 'Helvetica Neue', Arial, sans-serif; font-weight: 500; fill: ${MUTED}; }
]]></style>
${body}
</svg>`;
}

function text(cls, x, y, content, { size, fill, tracking = 0, anchor = 'start' } = {}) {
  // Inline style wins over the class fill. librsvg lets the stylesheet beat a fill attribute.
  const style = fill ? ` style="fill:${fill}"` : '';
  return `<text class="${cls}" x="${round(x)}" y="${round(y)}" font-size="${size}" letter-spacing="${round(tracking, 2)}" text-anchor="${anchor}"${style}>${esc(content)}</text>`;
}

function round(n, d = 1) {
  const f = 10 ** d;
  return Math.round(n * f) / f;
}

function rect(x, y, w, h, fill, extra = '') {
  return `<rect x="${round(x)}" y="${round(y)}" width="${round(w)}" height="${round(h)}" fill="${fill}"${extra}/>`;
}

function hline(x1, x2, y, color = RULE, sw = 1.5) {
  return `<line x1="${round(x1)}" y1="${round(y)}" x2="${round(x2)}" y2="${round(y)}" stroke="${color}" stroke-width="${sw}"/>`;
}

function wordmark(x, baseline, size, color = INK) {
  const tracking = -0.045 * size;
  const label = 'IdeaRevive';
  const width = measure(label, size, DISPLAY, tracking);
  const r = size * 0.155;
  const cx = x + width + size * 0.1 + r;
  const cy = baseline - size * 0.2;
  return `${text('d', x, baseline, label, { size, fill: color, tracking })}${`<circle cx="${round(cx)}" cy="${round(cy)}" r="${round(r)}" fill="${SIGNAL}"/>`}`;
}

function faviconMark(x, y, size) {
  const s = size / 64;
  return [
    rect(x, y, size, size, INK),
    rect(x + 17 * s, y + 14 * s, 10 * s, 36 * s, PAPER),
    rect(x + 35 * s, y + 40 * s, 10 * s, 10 * s, SIGNAL),
  ].join('');
}

function defaultOg() {
  const W = 1200;
  const H = 630;
  const x = 72;
  const right = 1128;
  const line1 = 'Get found on Google,';
  const line2a = 'Maps & ';
  const line2b = 'AI answers.';
  let size = 86;
  let tracking = -0.034 * size;
  while (size > 60 && (
    measure(line1, size, DISPLAY, tracking) > right - x
    || measure(line2a + line2b, size, DISPLAY, tracking) > right - x
  )) {
    size -= 2;
    tracking = -0.034 * size;
  }
  const lead =  size * 1.05;
  const y1 = 292;
  const y2 = y1 + lead;
  const line2aWidth = measure(line2a, size, DISPLAY, tracking);
  const parts = [];
  parts.push(rect(0, 0, W, H, PAPER));
  parts.push(faviconMark(x, 56, 52));
  parts.push(text('s', right, 88, 'idearevive.com', { size: 16, tracking: 0.4, anchor: 'end' }));
  parts.push(hline(x, right, 136));
  parts.push(text('d', x, y1, line1, { size, tracking }));
  parts.push(text('d', x, y2, line2a, { size, tracking }));
  parts.push(text('d', x + line2aWidth, y2, line2b, { size, tracking, fill: SIGNAL }));
  parts.push(wordmark(x, y2 + 86, 36));
  parts.push(rect(0, 528, W, 102, PAPER2));
  parts.push(hline(0, W, 528, RULE, 1.5));
  const meta = 'Digital marketing agency  ·  Hyderabad, India  ·  10+ years  ·  50+ clients';
  parts.push(text('s', x, 586, meta.toUpperCase(), { size: 16, tracking: 1.6 }));
  return { svg: svgDoc(W, H, parts.join('\n')), note: `${size}px` };
}

function pageOg(page) {
  const W = 1200;
  const H = 630;
  const x = 72;
  const right = 1128;
  const maxWidth = right - x - 8;
  const fitted = fitTitle(page.title, maxWidth);
  const top = 168;
  const bottom = 500;
  const gap = fitted.size * 1.06;
  const block = fitted.size + (fitted.lines.length - 1) * gap;
  let baseline = top + (bottom - top - block) / 2 + fitted.size * 0.78;
  if (baseline < 210) baseline = 210;
  const parts = [];
  parts.push(rect(0, 0, W, H, PAPER));
  parts.push(rect(x, 68, 12, 12, SIGNAL));
  parts.push(text('s', x + 24, 80, page.section.toUpperCase(), { size: 16, tracking: 2.2 }));
  parts.push(text('s', right, 80, 'idearevive.com', { size: 16, tracking: 0.4, anchor: 'end' }));
  parts.push(hline(x, right, 108));
  fitted.lines.forEach((line, i) => {
    parts.push(text('d', x, baseline + i * gap, line, { size: fitted.size, tracking: fitted.tracking }));
  });
  parts.push(rect(0, 528, W, 102, PAPER2));
  parts.push(hline(0, W, 528));
  parts.push(wordmark(x, 590, 36));
  const widest = Math.max(...fitted.lines.map((line) => measure(line, fitted.size, DISPLAY, fitted.tracking)));
  return {
    svg: svgDoc(W, H, parts.join('\n')),
    note: `${fitted.size}px · ${fitted.lines.length} line${fitted.lines.length === 1 ? '' : 's'} · ${Math.round(widest)}px`,
    lines: fitted.lines,
    overflow: widest > right - x + 2,
  };
}

